import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CANn83f8.js";const s="/images/features/dashboard.png",i="/images/features/dashboard-2.png",m=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md","lastUpdated":1790713879000}'),r={name:"features/dashboard.md"};function d(h,e,l,c,p,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard gives you a monthly overview of your financial activity.</p><p>It brings together your income, spending, categories, tags, budgets and goals so you can understand where your money went and what needs your attention. Use the month selector in the top right corner to review a different period.</p><p>The heading also shows how many transactions and accounts are included in the selected month.</p><p><img src="'+s+'" alt="Dashboard"><img src="'+i+'" alt="Dashboard"></p><h2 id="monthly-summary" tabindex="-1">Monthly summary <a class="header-anchor" href="#monthly-summary" aria-label="Permalink to &quot;Monthly summary&quot;">​</a></h2><p>The summary at the top of the Dashboard displays:</p><ul><li><strong>Income:</strong> all recorded money coming in</li><li><strong>Spending:</strong> recorded money going out and the percentage of income used</li><li><strong>Income left:</strong> income minus spending</li><li><strong>Income left (%):</strong> the share of recorded income that has not been spent</li></ul><p>Positive income-left values are displayed in green. If spending is greater than income, the value is displayed in red.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Income left is not your bank balance or a spending allowance. Upcoming bills and planned savings are not deducted.</p></div><p>Transactions that are in transfer type categories, and ignored transactions are excluded from the summary.</p><h2 id="uncategorized-transactions" tabindex="-1">Uncategorized transactions <a class="header-anchor" href="#uncategorized-transactions" aria-label="Permalink to &quot;Uncategorized transactions&quot;">​</a></h2><p>The Dashboard warns you when transactions still need categorizing. It shows the number of uncategorized transactions and their total value for the selected month.</p><p>Uncategorized expenses are excluded from spending, which means the displayed income-left amount may be higher than it should be.</p><p>To review them:</p><ol><li>Click <strong>Categorize now</strong>.</li><li>Select a transaction from the panel.</li><li>Assign its budget or category.</li><li>Save the transaction.</li></ol><p>When every transaction in the selected month is categorized, the Dashboard displays <strong>All caught up</strong>.</p><h2 id="spending-pace" tabindex="-1">Spending pace <a class="header-anchor" href="#spending-pace" aria-label="Permalink to &quot;Spending pace&quot;">​</a></h2><p>The spending-pace chart shows how your spending accumulates throughout the month. It includes:</p><ul><li>Your cumulative recorded spending</li><li>An income pace reference</li><li>Your average daily spending</li><li>Projected spending for the complete month</li></ul><p>Enable <strong>Compare with previous month</strong> to add the previous month&#39;s cumulative spending to the chart.</p><p>Hover over the chart to inspect the values for a particular day.</p><h2 id="what-stands-out" tabindex="-1">What stands out <a class="header-anchor" href="#what-stands-out" aria-label="Permalink to &quot;What stands out&quot;">​</a></h2><p>The <strong>What stands out</strong> section highlights notable patterns in the selected month. Depending on your activity, these insights can call attention to your spending pace, remaining income or changes in category spending.</p><p>If no activity has been recorded for the month, there may not be any insights to display.</p><h2 id="spending-distribution" tabindex="-1">Spending distribution <a class="header-anchor" href="#spending-distribution" aria-label="Permalink to &quot;Spending distribution&quot;">​</a></h2><p>The spending-distribution chart groups recorded spending by category.</p><p>Hover over a section of the chart to see that category&#39;s amount. The list beside the chart shows each category&#39;s:</p><ul><li>Share of total spending</li><li>Recorded amount</li><li>Increase or decrease compared with the previous month</li></ul><p>Changes smaller than 5% are not highlighted.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Categorize transactions consistently to make the spending distribution and month-to-month comparisons more accurate.</p></div><h2 id="tag-analysis" tabindex="-1">Tag analysis <a class="header-anchor" href="#tag-analysis" aria-label="Permalink to &quot;Tag analysis&quot;">​</a></h2><p>Tag analysis groups spending using the tags assigned to your transactions. It shows up to ten tags, together with:</p><ul><li>The number of matching transactions</li><li>The tag&#39;s share of tagged spending</li><li>The total amount</li><li>The change from the previous month</li></ul><p>Click <strong>Browse by tag</strong> to open the Transactions page and explore the underlying activity.</p><h2 id="goals-and-budgets" tabindex="-1">Goals and budgets <a class="header-anchor" href="#goals-and-budgets" aria-label="Permalink to &quot;Goals and budgets&quot;">​</a></h2><p>The Dashboard shows progress for your active goals and budgets.</p><p>For each goal, you can see the amount saved, the target amount and the percentage completed. Click <strong>Manage</strong> to open the Goals page.</p><p>For each budget, you can see the amount used compared with its limit. Click <strong>Manage</strong> to review or update your budgets.</p><h2 id="latest-activity" tabindex="-1">Latest activity <a class="header-anchor" href="#latest-activity" aria-label="Permalink to &quot;Latest activity&quot;">​</a></h2><p>The <strong>Latest activity</strong> section lists your most recent transactions for the selected period. Each entry shows the payee, date and amount.</p><p>Click a transaction to open its details, or click <strong>All transactions</strong> to view the complete transaction list.</p><h2 id="import-transactions" tabindex="-1">Import transactions <a class="header-anchor" href="#import-transactions" aria-label="Permalink to &quot;Import transactions&quot;">​</a></h2><p>Click <strong>Import CSV</strong> in the top right corner to add transactions from a supported bank statement. After importing, review uncategorized transactions so the Dashboard totals and comparisons reflect the new activity.</p><p>For the complete import workflow, see <a href="./transactions">Transactions</a>.</p>',45)])])}const b=t(r,[["render",d]]);export{m as __pageData,b as default};
